@extends('layouts.app',['title'=>'WhatsApp Centre']) @section('content')<div class="card panel" style="margin-bottom:18px"><div class="panel-title"><div><h3>WhatsApp QR device</h3><div class="eyebrow">Unofficial local connector · internet required</div></div><span class="badge" id="wa-state">Checking…</span></div><div style="display:grid;grid-template-columns:220px 1fr;gap:20px;align-items:center"><div id="wa-qr" style="min-height:180px;display:grid;place-items:center;background:#f7f7fb;border-radius:12px">QR appears when linking is required</div><div><p><strong>Risk notice:</strong> WhatsApp Web automation is unofficial and may disconnect, break, or cause number restriction. Use a dedicated school number.</p><p id="wa-detail" class="eyebrow"></p><form method="post" action="{{route('communication.connector.logout')}}">@csrf<button class="button">Disconnect device</button></form></div></div></div><script>fetch('{{route('communication.connector')}}').then(async r=>{let d=await r.json();let h=d.health||{};document.getElementById('wa-state').textContent=h.state||'unavailable';document.getElementById('wa-detail').textContent=h.account?'Linked account: +'+h.account:(d.error||h.last_error||'');if(d.qr&&d.qr.qr)document.getElementById('wa-qr').innerHTML='<img alt="WhatsApp QR" style="max-width:200px" src="'+d.qr.qr+'">'}).catch(()=>document.getElementById('wa-state').textContent='unavailable')</script><div class="heading"><div><div class="eyebrow">Communication · Controlled WhatsApp automation</div><h1>WhatsApp Centre</h1></div><span class="badge">Connector isolated</span></div>@if(session('success'))<div style="padding:14px;background:#e8f8ee;color:#237a46;border-radius:11px;margin-bottom:16px">{{session('success')}}</div>@endif<div class="grid"><form method="post" action="{{route('communication.store')}}" class="card panel">@csrf<div class="panel-title"><h3>Create parent message</h3></div><label style="font-weight:700">Template<select name="template_id" style="display:blo